-- Reforça explicações curtas do catálogo de Legislação Institucional,
-- corrige uma referência legal trocada e registra a conferência normativa.
update public.curated_question_catalog
set explanation = case external_item_key
when 'pcac-lc129-art101-first-group-25' then 'A art. 101, I, da LC nº 129/2004 enquadra no primeiro grupo a permuta de horário de serviço sem autorização expressa da autoridade policial hierarquicamente superior. Exemplo: dois policiais combinam trocar o plantão por conta própria, sem autorização formal da chefia competente. A irregularidade não é simplesmente conversar sobre a escala: é efetivar a troca sem a autorização exigida. Dica de prova: a expressão “sem autorização expressa” é o ponto que define a transgressão.'
when 'pcac-lc129-art103-absence-26' then 'O art. 103, I, da LC nº 129/2004 classifica no terceiro grupo a ausência injustificada do policial civil por até 30 dias consecutivos. A questão cobra a classificação disciplinar prevista na lei especial da Polícia Civil. Atenção à expressão “até 30 dias”: não troque esse enquadramento por outras hipóteses de abandono ou inassiduidade previstas em normas gerais. Na prova, localize primeiro o número de dias e depois associe ao grupo.'
when 'pcac-lc129-art128-syndicance-30' then 'O art. 128, § 1º, da LC nº 129/2004 assegura dez dias para apresentação de defesa escrita depois de concluída a produção de provas na sindicância. O prazo começa nessa etapa processual, não na abertura da sindicância. Exemplo: encerradas as diligências e a coleta de provas, o sindicado recebe o prazo legal para responder por escrito. Dica: não confunda prazo de defesa com prazo para a Administração concluir a apuração.'
when 'pcac-lc129-art138-witnesses-32' then 'O art. 138, § 1º, da LC nº 129/2004 permite ao acusado arrolar até oito testemunhas no PAD. “Até oito” significa limite máximo, não número obrigatório: o acusado pode indicar menos. Em questão objetiva, desconfie de alternativas que importam automaticamente o limite de testemunhas do processo penal, pois aqui a pergunta exige a regra específica do estatuto disciplinar da Polícia Civil.'
when 'pcac-lc129-groups-04' then 'O art. 101, I, da LC nº 129/2004 classifica como transgressão do primeiro grupo trocar ou permutar horário de serviço sem autorização expressa da autoridade hierarquicamente superior. O núcleo da conduta é a alteração da escala por iniciativa dos envolvidos, sem autorização formal. A questão usa “trocar” em vez de “permutar”, mas descreve a mesma situação jurídica. Dica: procure no enunciado a ausência de autorização expressa.'
when 'pcac-lc129-pad-06' then 'O art. 129 da LC nº 129/2004 exige PAD quando a infração, pela sua natureza, puder levar à aplicação da pena de demissão. A sindicância serve para apuração preliminar ou para hipóteses de menor gravidade, mas não substitui o PAD quando a sanção possível exige esse procedimento formal. Exemplo: se os fatos podem justificar demissão, a Administração deve instaurar PAD com contraditório e ampla defesa; não basta encerrar o caso em sindicância.'
when 'pcac-lc129-prescription-09' then 'O art. 118, I, da LC nº 129/2004 fixa em seis meses a prescrição da falta sujeita à advertência. A regra relaciona o prazo à penalidade em tese aplicável: advertência = seis meses. Compare com o inciso II, que prevê dois anos para falta sujeita à suspensão. Dica de memorização: associe cada prazo à gravidade da sanção e leia o artigo inteiro antes de marcar, porque as alternativas costumam trocar os períodos.'
when 'pcac-lc129-review-13' then 'O art. 157, IV, da LC nº 129/2004 admite a revisão quando, depois da decisão, surgir prova da inocência do punido. O elemento decisivo é a prova nova capaz de alterar a conclusão do processo. Não basta repetir que a penalidade foi injusta ou demonstrar mero inconformismo. Exemplo: documento ou registro descoberto posteriormente que comprova que o servidor não praticou a conduta. Dica: revisão exige fundamento concreto, não simples discordância.'
when 'pcac-lc129-suspension-prescription-10' then 'O art. 118, II, da LC nº 129/2004 estabelece dois anos para a prescrição da falta sujeita à suspensão. Compare os prazos do próprio artigo: seis meses para advertência e dois anos para suspensão. A banca costuma trocar os períodos entre as penalidades. Primeiro identifique a sanção prevista para a falta; depois associe o prazo correspondente.'
when 'pcac-lc303-delegate-classes-46' then 'O art. 4º, § 1º, da LC nº 303/2015 organiza a carreira de Delegado em cinco classes, em ordem crescente: I, II, III, IV e Especial (V). O § 2º também extingue, para Delegado, a progressão por referências salariais. Portanto, não confunda classe com referência: a estrutura da carreira é formada por cinco classes, e a última recebe o nome “Especial”.'
when 'pcac-lc303-delegate-degree-45' then 'O art. 2º da LC nº 303/2015 declara o cargo de Delegado privativo de bacharel em Direito. Atenção: isso identifica a formação acadêmica exigida, mas não esgota todos os requisitos atuais de ingresso. A Lei Orgânica Nacional (Lei nº 14.735/2023, art. 20, § 3º) também prevê três anos de atividade jurídica ou policial para o cargo de Delegado. Dica: diferencie escolaridade do requisito adicional de experiência.'
when 'pcac-lc39-petition-decision-58' then 'O art. 156, parágrafo único, da LC nº 39/1993 determina dois prazos diferentes: o requerimento e o pedido de reconsideração devem ser despachados em cinco dias e decididos em até 30 dias. “Despachar” é dar andamento/encaminhar; “decidir” é resolver o pedido. Não confunda esses prazos internos com o prazo de 30 dias do art. 158 para o servidor apresentar pedido de reconsideração ou recurso. Dica: 5 dias para despacho; 30 dias para decisão; 30 dias para interpor o recurso.'
when 'pcac-lc526-appeal-effects-19' then 'O art. 73, § 10, da LC nº 129/2004, com redação da LC nº 526/2026, prevê que o recurso contra a proposta de exoneração no estágio probatório seja recebido nos efeitos devolutivo e suspensivo. Devolutivo: a matéria é reexaminada pela autoridade competente. Suspensivo: a proposta não produz seus efeitos enquanto o recurso aguarda decisão, nos termos da regra. Dica: quando o enunciado citar expressamente o § 10, marque os dois efeitos.'
when 'pcac-lc526-course-absence-20' then 'O art. 79-B da LC nº 129/2004, incluído pela LC nº 526/2026, considera requisito essencial a frequência no curso específico de formação. Mais de 25% de faltas injustificadas em qualquer disciplina pode levar à exoneração por não preenchimento do requisito. Atenção à expressão “mais de 25%”: não transforme o limite em “25% ou mais”. Exemplo: 26% de faltas injustificadas ultrapassa o limite descrito no enunciado.'
when 'pcac-lc526-course-termination-21' then 'O art. 79-B, I, da LC nº 129/2004, incluído pela LC nº 526/2026, trata o curso específico de formação como etapa eliminatória do estágio probatório. A reprovação em qualquer disciplina pode caracterizar o não preenchimento de requisito essencial e resultar em exoneração, conforme a hipótese legal. Não é simples atraso de promoção nem advertência automática: o efeito decorre do caráter eliminatório do curso e do descumprimento do requisito.'
when 'pcac-lc526-first-assignment-23' then 'O art. 79-C, § 1º, da LC nº 129/2004, incluído pela LC nº 526/2026, determina que a primeira lotação considere a classificação final obtida nas avaliações do curso específico de formação. Assim, a nota/classificação do curso é o critério indicado pela regra, e não exclusivamente a posição obtida no concurso de ingresso. Dica: se o enunciado disser “após o curso de formação”, procure a regra especial de primeira lotação.'
when 'pcac-lc526-probation-duration-17' then 'O art. 73 da LC nº 129/2004, na redação vigente após a LC nº 526/2026, estabelece estágio probatório de três anos. Esse período corresponde à avaliação especial para confirmar a aptidão do servidor no cargo; não deve ser confundido com a duração do curso de formação. Dica de prova: memorize três anos e confira se a questão está falando de estágio probatório ou de curso de formação.'
when 'pcac-national-custody-60' then 'O art. 40 da Lei nº 14.735/2023 estabelece a vedação de custódia de preso ou adolescente infrator nas unidades da Polícia Civil, ressalvada a hipótese excepcional de interesse fundamentado na investigação policial. A exceção exige justificativa ligada à investigação; falta de vaga, conveniência genérica ou decisão sem motivação não bastam por si sós. Dica: a palavra-chave é “interesse fundamentado na investigação”.'
when 'pcac-national-day-64' then 'O art. 47 da Lei nº 14.735/2023 fixa 5 de abril como Dia Nacional da Polícia Civil. É uma questão literal, típica de memorização de data. Para evitar troca com datas de outras instituições, associe diretamente: Polícia Civil = 5 de abril. A data está expressamente prevista na Lei Orgânica Nacional.'
when 'pcac-national-local-laws-65' then 'O art. 49 da Lei nº 14.735/2023 preserva as leis locais naquilo que não for incompatível com a Lei Orgânica Nacional. Isso significa que a lei federal não revogou automaticamente toda a legislação estadual: as regras estaduais compatíveis continuam válidas; as incompatíveis não prevalecem. Dica: a banca pode trocar “permanecem válidas no que forem compatíveis” por “todas foram revogadas” — essa afirmação é incorreta.'
when 'pcac-national-susp-36' then 'O art. 2º da Lei nº 14.735/2023 inclui as Polícias Civis entre os integrantes operacionais do Sistema Único de Segurança Pública (Susp). Isso significa integração operacional ao sistema nacional de segurança pública, sem transformar a Polícia Civil em órgão do Judiciário, do Ministério Público ou do sistema penitenciário. Dica: memorize a expressão legal “integrantes operacionais do Susp”.'
else explanation end,
legal_basis = case
when external_item_key like 'pcac-lc129-%' then jsonb_build_array(jsonb_build_object('lei','Lei Complementar Estadual nº 129/2004','title','Lei Orgânica da Polícia Civil e Estatuto dos Policiais Civis do Estado do Acre','url','https://legis.ac.gov.br/detalhar/674-0','artigo',case external_item_key
 when 'pcac-lc129-art101-first-group-25' then '101, I' when 'pcac-lc129-art103-absence-26' then '103, I'
 when 'pcac-lc129-art128-syndicance-30' then '128, § 1º' when 'pcac-lc129-art138-witnesses-32' then '138, § 1º'
 when 'pcac-lc129-groups-04' then '101, I' when 'pcac-lc129-pad-06' then '129'
 when 'pcac-lc129-prescription-09' then '118, I' when 'pcac-lc129-review-13' then '157, IV'
 when 'pcac-lc129-suspension-prescription-10' then '118, II' end))
when external_item_key like 'pcac-lc303-%' then jsonb_build_array(
 jsonb_build_object('lei','Lei Complementar Estadual nº 303/2015','title','Estrutura da carreira de Delegado de Polícia Civil','url','https://legis.ac.gov.br/detalhar/3990-0','artigo',case external_item_key when 'pcac-lc303-delegate-classes-46' then '4º, §§ 1º e 2º' else '2º' end),
 jsonb_build_object('lei','Lei nº 14.735/2023','title','Lei Orgânica Nacional das Polícias Civis','url','https://www2.camara.leg.br/legin/fed/lei/2023/lei-14735-23-novembro-2023-794983-normaatualizada-pl.html','artigo','20, § 3º'))
when external_item_key='pcac-lc39-petition-decision-58' then jsonb_build_array(jsonb_build_object('lei','Lei Complementar Estadual nº 39/1993','title','Estatuto dos Servidores Públicos Civis do Estado do Acre','url','https://legis.ac.gov.br/detalhar/110','artigo','156, parágrafo único'))
when external_item_key like 'pcac-lc526-%' then jsonb_build_array(
 jsonb_build_object('lei','Lei Complementar Estadual nº 129/2004, com redação da LC nº 526/2026','title','Lei Orgânica da Polícia Civil do Estado do Acre — texto consolidado','url','https://legis.ac.gov.br/detalhar/674-0','artigo',case external_item_key
  when 'pcac-lc526-appeal-effects-19' then '73, § 10' when 'pcac-lc526-course-absence-20' then '79-B'
  when 'pcac-lc526-course-termination-21' then '79-B, I' when 'pcac-lc526-first-assignment-23' then '79-C, § 1º'
  when 'pcac-lc526-probation-duration-17' then '73' end),
 jsonb_build_object('lei','Lei Complementar Estadual nº 526/2026','title','Alteração da Lei Orgânica da Polícia Civil','url','https://legis.ac.gov.br/detalhar/6874'))
when external_item_key like 'pcac-national-%' then jsonb_build_array(jsonb_build_object('lei','Lei nº 14.735/2023','title','Lei Orgânica Nacional das Polícias Civis — texto atualizado','url','https://www2.camara.leg.br/legin/fed/lei/2023/lei-14735-23-novembro-2023-794983-normaatualizada-pl.html','artigo',case external_item_key
 when 'pcac-national-custody-60' then '40' when 'pcac-national-day-64' then '47'
 when 'pcac-national-local-laws-65' then '49' when 'pcac-national-susp-36' then '2º' end))
else legal_basis end,
verified_at=now(), law_version_checked_at=now()
where subject='Legislação Institucional'
and external_item_key in (
'pcac-lc129-art101-first-group-25','pcac-lc129-art103-absence-26','pcac-lc129-art128-syndicance-30',
'pcac-lc129-art138-witnesses-32','pcac-lc129-groups-04','pcac-lc129-pad-06','pcac-lc129-prescription-09',
'pcac-lc129-review-13','pcac-lc129-suspension-prescription-10','pcac-lc303-delegate-classes-46',
'pcac-lc303-delegate-degree-45','pcac-lc39-petition-decision-58','pcac-lc526-appeal-effects-19',
'pcac-lc526-course-absence-20','pcac-lc526-course-termination-21','pcac-lc526-first-assignment-23',
'pcac-lc526-probation-duration-17','pcac-national-custody-60','pcac-national-day-64',
'pcac-national-local-laws-65','pcac-national-susp-36'
);
